{
  "background_need": "Twelve self-employed artists in the fictional Northlight district lack practical skills for pricing and customer development. They have access to a shared workshop for a six-month pilot.",
  "objectives": [
    {
      "id": "O1",
      "description": "Participants successfully test one realistic service offer with external customers."
    },
    {
      "id": "O2",
      "description": "Participants can accurately explain the costs and value of their proposed service offers."
    }
  ],
  "target_groups": [
    "Twelve self-employed artists in the Northlight district"
  ],
  "preliminary_activities": [
    {
      "id": "A1",
      "description": "Facilitate a workshop session on cost calculation and value articulation for all participants.",
      "objective_ids": ["O2"]
    },
    {
      "id": "A2",
      "description": "Support participants in defining one service offer each and identifying potential fictional customers.",
      "objective_ids": ["O1"]
    }
  ],
  "expected_results": [
    {
      "id": "R1",
      "description": "Each participant has defined a specific service offer.",
      "activity_ids": ["A2"]
    },
    {
      "id": "R2",
      "description": "Participants have calculated and documented their costs.",
      "activity_ids": ["A1"]
    },
    {
      "id": "R3",
      "description": "At least 5 participants have conducted a mock customer interaction with a defined offer.",
      "activity_ids": ["A2"]
    }
  ],
  "proposed_indicators": [
    {
      "id": "I1",
      "description": "Percentage of participants who have defined a service offer.",
      "result_ids": ["R1"],
      "measurement_method": "Review of submitted service proposal documents by facilitator team."
    },
    {
      "id": "I2",
      "description": "Average percentage of total costs correctly identified per participant.",
      "result_ids": ["R2"],
      "measurement_method": "Comparison of participant-calculated costs against a standardized cost model provided in the workshop."
    },
    {
      "id": "I3",
      "description": "Number of participants who completed at least one mock customer interaction.",
      "result_ids": ["R3"],
      "measurement_method": "Count of signed mock transaction logs submitted by participants."
    }
  ],
  "assumptions": [
    "The twelve artists are able to attend all scheduled workshop sessions without significant conflict.",
    "A sufficient number of fictional customers can be identified and engaged for the pilot period.",
    "The shared workshop facility remains available throughout the six-month duration."
  ],
  "open_questions": [
    "What specific pricing models do these artists currently use, if any?",
    "Are there existing local networks that could serve as sources for fictional customers?",
    "Is there a verified funding programme eligible for this type of capacity building activity?"
  ]
}
